 /** The environment variable name for one field of a secret. */
 export function envName(path: string, field: string): string {
-  throw new Error("not implemented");
+  if (field === "") throw new RangeError("field must not be empty");
+  const last = path.split("/").filter(Boolean).pop() ?? "";
+  const name = `${last}_${field}`
+    .toUpperCase()
+    .replace(/[^A-Z0-9]+/g, "_")
+    .replace(/^_+|_+$/g, "");
+  return /^[0-9]/.test(name) ? `_${name}` : name;
 }
+
+const SAFE_VALUE = /^[A-Za-z0-9_@%+=:,./-]*$/;
+
+/** Render one value for a dotenv line. */
+function renderValue(value: string): string {
+  if (value === "") return "";
+  if (SAFE_VALUE.test(value)) return value;
+  const escaped = value
+    .replace(/\\/g, "\\\\")
+    .replace(/"/g, '\\"')
+    .replace(/\$/g, "\\$")
+    .replace(/\n/g, "\\n")
+    .replace(/\r/g, "\\r");
+  return `"${escaped}"`;
+}
+
+const NAME_RE = /^[A-Z_][A-Z0-9_]*$/;

 /** Render variables as the lines of a dotenv file. */
 export function renderEnvFile(vars: Record<string, string>): string {
-  throw new Error("not implemented");
+  const names = Object.keys(vars).sort();
+  const lines: string[] = [];
+  for (const name of names) {
+    if (!NAME_RE.test(name)) throw new RangeError(`invalid variable name: ${name}`);
+    lines.push(`${name}=${renderValue(vars[name])}`);
+  }
+  return lines.length ? `${lines.join("\n")}\n` : "";
 }

